NoteSolution Exercice 3





def validatePort(port: Int): Option[Int] = 
  if (port &gt;= 1 && port &lt;= 65535) Some(port)
  else None

def validateHost(host: String): Option[String] = 
  if (host.trim.nonEmpty) Some(host.trim)
  else None

def validateTimeout(timeout: Int): Option[Int] = 
  if (timeout &gt; 0) Some(timeout)
  else None

def validateConfig(config: RawConfig): Option[ValidatedConfig] = 
  for {
    host &lt;- config.host.flatMap(validateHost)
    port &lt;- config.port.flatMap(validatePort)
    timeout &lt;- config.timeout.flatMap(validateTimeout)
  } yield ValidatedConfig(host, port, timeout)

def buildUrl(config: ValidatedConfig): String = 
  s"http://${config.host}:${config.port}"

def validateConfigWithDefaults(config: RawConfig): ValidatedConfig = 
  ValidatedConfig(
    host = config.host.flatMap(validateHost).getOrElse("localhost"),
    port = config.port.flatMap(validatePort).getOrElse(8080),
    timeout = config.timeout.flatMap(validateTimeout).getOrElse(3000)
  )




